-- Nexmark q17 on flink, BLACKHOLE sink variant. Auction statistics: five
-- aggregates per auction per 10s window. Flink casts the price to DOUBLE
-- inside AVG for the same reason q4 does: AVG of an exact numeric type
-- truncates there, while clink's AVG already returns a real number. The row-
-- count gate never saw the difference; a value-level comparison does.
-- GENERATED by queries/gen_queries.py from the single cross-engine
-- definition. Edit that file, not this one.
CREATE TABLE bid (
  `auction` BIGINT, `bidder` BIGINT, `price` BIGINT, `channel` STRING, `url` STRING, `datetime` BIGINT,
  ts AS TO_TIMESTAMP_LTZ(`datetime`, 3),
  WATERMARK FOR ts AS ts - INTERVAL '4' SECOND
) WITH (
  'connector' = 'kafka',
  'topic' = 'nx-bid',
  'properties.bootstrap.servers' = 'kafka:29092',
  'properties.group.id' = 'flink-q17bh-bid',
  'scan.startup.mode' = 'earliest-offset',
  'format' = 'json',
  'json.ignore-parse-errors' = 'false'
);
CREATE TABLE sink_q17 (`auction` BIGINT, `total` BIGINT, `minp` BIGINT, `maxp` BIGINT, `avgp` DOUBLE) WITH ('connector' = 'blackhole');
INSERT INTO sink_q17
SELECT auction, COUNT(*) AS total, MIN(price) AS minp, MAX(price) AS maxp, AVG(CAST(price AS DOUBLE)) AS avgp FROM TABLE(TUMBLE(TABLE bid, DESCRIPTOR(ts), INTERVAL '10' SECOND)) GROUP BY window_start, window_end, auction;
